mapper.select:
SELECT ex.*, YEAR(#{query.workYearCompareDate}) - YEAR(ex.present_job_date) AS yearDiff FROM tb_expert ex left join sys_user su on su.user_id = ex.user_id and su.del_flag = 0
ex.del_flag = 0
and not exists( select bee.id from tb_bidding_evaluat_expert bee inner join tb_procurement_scheme ps on ps.id = bee.scheme_id inner join tb_tender_notice tn on bee.notice_id = tn.id where bee.del_flag = 0 and ps.del_flag = 0 and tn.del_flag = 0 and bee.is_join = 1 and bee.expert_id = ex.id and tn.notice_status = #{query.noticeStatus})
and ex.expert_name like CONCAT('%', #{query.expertName}, '%')
and ex.expert_phone like CONCAT('%', #{query.expertPhone}, '%')
and ex.belong_organization = #{query.belongOrganization}
and ex.expert_type = #{query.expertType}
and find_in_set(ex.expert_type, #{query.expertTypes})
and ex.business_type = #{query.businessType}
and find_in_set(ex.business_type, #{query.businessTypes})
and (su.dept_id = #{query.deptId} or su.dept_id in ( select t.dept_id from sys_dept t where find_in_set(#{query.deptId}, ancestors)))
and (
(su.dept_id = #{deptIdItem} or su.dept_id in ( select t.dept_id from sys_dept t where find_in_set(#{deptIdItem}, ancestors)))
)
and ex.major like CONCAT('%', #{query.major}, '%')
and ex.technical_titles >= #{query.technicalTitles}
and ex.registered_certificate like CONCAT('%', #{query.registeredCertificate}, '%')
and (YEAR(#{query.workYearCompareDate}) - YEAR(ex.present_job_date)) >= #{query.workYear}
and not find_in_set(ex.id, #{query.notIncludeExpertIds})
and ex.expert_state = #{query.expertState}
and ex.state = #{query.state}
and ex.user_id = #{query.userId}

